CREATE OR REPLACE FUNCTION calculate_fei(
    eng_rate NUMERIC,
    social_score NUMERIC,
    active_days SMALLINT,
    avg_sessions SMALLINT
) RETURNS NUMERIC AS $$
BEGIN
    RETURN (eng_rate * 0.4) + (social_score / 100.0 * 0.3) + (active_days::NUMERIC / 7.0 * 0.2) + (avg_sessions::NUMERIC / 10.0 * 0.1);
END;
$$ LANGUAGE plpgsql;
